"""One-shot original-source metadata binding, read-only guard check by default.
Parent must explicitly select --arm for a reviewed, necessary released boundary.
No waiting loop, GPU query, payload read, lease, deployment or resume.
"""
from pathlib import Path
import argparse,base64,zlib,hashlib,json,sys,time,datetime
p=argparse.ArgumentParser();p.add_argument('--number',required=True);p.add_argument('--arm',action='store_true');a=p.parse_args();assert a.number.isdecimal() and len(a.number)<=3
raw=zlib.decompress(base64.b64decode(''));assert hashlib.sha256(raw).hexdigest()=="faa59ec12ccd01848652368f6cc5fce74d36f98db7556253fe31cb05749a91e7"
ns={'__name__':'source22_run_specific_stop'};exec(compile(raw,'stop-stable-faa59ec1','exec'),ns)
BASE=ns['BASE'];RUN=ns['RUN'];OP=ns['OP'];sys.dont_write_bytecode=True;sys.path.insert(0,str(OP/'source/src'))
from w1a1_eagle import direct_training_runtime as rt
runtime,cfg=rt.authenticate_runtime(OP/'runtime.json');assert rt.metadata(OP/'runtime.json')[1]==ns['RUNTIME_SHA'];lane=rt.checked(cfg['lane']);rt.current_control(lane);rt.keeper_environment(cfg['keeper'])
assert {k:ns['identity'](v['pid']) for k,v in ns['EXPECTED'].items()}==ns['EXPECTED']
children=Path('/proc/9292/task/9292/children').read_text().strip()
if children:
 print(json.dumps({'status':'REFUSED','reason':'live controller child','children':children,'signal_sent':False,'at':datetime.datetime.now(datetime.timezone.utc).isoformat()}));raise SystemExit(0)
assert rt.metadata(RUN/'training/budget-used.json')[0]['active_attempt'] is None,'active clock'
paths={'state':RUN/'state.json','latest':RUN/'training/checkpoints/latest.json','budget':RUN/'training/budget-used.json','status':RUN/'training/status.json','active':OP/'active-window.json','progress':RUN/'resource-handoff-progress.json'}
spec=rt.checked(lane['config']);paths['canonical']=Path(spec['data']['cache_root'])/'cache-state.json'
values={};records={};fingerprints={};started=time.time()
def read(name,path):
 before=ns['fingerprint'](path);value,digest=rt.metadata(path);assert before==ns['fingerprint'](path),'changed binding metadata'
 values[name]=value;records[name]={'path':str(path),'sha256':digest};fingerprints[str(path)]=before
for name,path in paths.items():read(name,path)
state=values['state'];active=values['active'];assert state['status']=='restoring_shards' and state.get('pending_shard_resume') is True,'not original shard boundary'
assert not any(row.get('original_catalog')==active['catalog'] for row in state.get('prepared_window_retirements',[])),'current catalog already retired'
read('receipt',Path(state['train_receipt']['path']));read('catalog',Path(active['catalog']['path']))
assert records['receipt']==state['train_receipt'] and records['catalog']==active['catalog']
assert all(ns['fingerprint'](path)==before for path,before in fingerprints.items()),'binding raced'
assert 0<=time.time()-started<=15,'binding acquisition too slow'
binding={'schema':'source22_stable_endpoint_binding_v1','observed_unix':started,'expires_unix':started+60,'minimum_release_unix':fingerprints[str(Path(state['train_receipt']['path']))][-2]/1e9,'scientific_config_sha256':lane['config']['sha256'],'gpu_uuid':lane['gpu_uuid'],'files':records}
path=BASE/('runs/dspark-source22-fast-stable-binding-20261016-'+a.number+'.json');rt.write_new(path,binding);digest=hashlib.sha256(path.read_bytes()).hexdigest()
args=['--binding',str(path),'--binding-sha256',digest]
if a.arm:args+=['--output',str(BASE/('runs/dspark-source22-fast-stable-stop-20261016-'+a.number))]
else:args+=['--check']
print(json.dumps({'binding_path':str(path),'binding_sha256':digest,'requested_arm':a.arm,'at':datetime.datetime.now(datetime.timezone.utc).isoformat()}),flush=True)
ns['main'](args)
